B64_0864d0d8
python3 - <<'PY'
from PIL import Image
for n in ["seca","brote","flor","fruto"]:
    p=f"assets/mascot/ovejita_planta_{n}.png"
    try:
        im=Image.open(p).convert("RGBA")
        im.thumbnail((500,500), Image.LANCZOS)
        im.save(p)
        print("optimizada", p, im.size)
    except Exception as e:
        print("aviso", p, e)
